export const physicalEducationBank: SubjectBank = {
  short: [
    { question: "What is the difference between aerobic and anaerobic exercise?", answer: "Aerobic exercise uses oxygen to produce energy and can be sustained for long periods (e.g. running, cycling). Anaerobic exercise occurs without oxygen, produces energy rapidly but only for short bursts, and produces lactic acid (e.g. sprinting, weightlifting).", marks: 2, hint: "One uses oxygen; the other doesn't", acceptedAnswers: ["aerobic uses oxygen, anaerobic does not", "aerobic = with oxygen, sustained; anaerobic = without oxygen, short bursts", "aerobic uses oxygen for long duration; anaerobic produces lactic acid in short bursts", "with oxygen vs without oxygen"] },
    { question: "What is 'cardiac output' and how is it calculated?", answer: "Cardiac output is the volume of blood pumped by the heart per minute. Cardiac output = heart rate × stroke volume.", marks: 2, hint: "Heart rate × stroke volume", acceptedAnswers: ["cardiac output = heart rate × stroke volume", "heart rate multiplied by stroke volume", "CO = HR × SV", "blood pumped per minute = heart rate times stroke volume"] },
    { question: "Name the three types of muscle fibres and their characteristics.", answer: "Type I (slow twitch): fatigue resistant, aerobic, used in endurance. Type IIa (fast oxidative glycolytic): moderate speed, mix of aerobic and anaerobic. Type IIb (fast twitch): powerful and fast, fatigue quickly, anaerobic, used in explosive activities.", marks: 3, hint: "Slow twitch vs fast twitch — which is used for a marathon vs a 100m sprint?", acceptedAnswers: ["Type I slow twitch, Type IIa fast oxidative, Type IIb fast twitch", "slow twitch (endurance), fast oxidative glycolytic (mixed), fast twitch (explosive)", "Type I: aerobic/endurance; Type IIa: mixed; Type IIb: anaerobic/explosive"] },
    { question: "What is 'RICE' in the treatment of sports injuries?", answer: "RICE stands for: Rest (stop the activity); Ice (apply ice to reduce swelling); Compression (bandage to limit swelling); Elevation (raise the injured limb above heart level).", marks: 2, hint: "An acronym for treating soft tissue injuries", acceptedAnswers: ["Rest, Ice, Compression, Elevation", "rest ice compression elevation", "R=rest, I=ice, C=compression, E=elevation", "stop activity, apply ice, bandage, raise limb"] },
    { question: "What are the FITT principles of training?", answer: "Frequency (how often you train), Intensity (how hard you work), Time (duration of each session), Type (mode of exercise). Together these variables can be manipulated to apply progressive overload and improve fitness.", marks: 2, hint: "Four variables you can change in any training programme", acceptedAnswers: ["Frequency, Intensity, Time, Type", "F=frequency, I=intensity, T=time, T=type", "how often, how hard, how long, what exercise", "frequency intensity time type"] },
    { question: "What is 'VO2 max'?", answer: "VO2 max is the maximum volume of oxygen the body can consume per minute per kilogram of body weight during intense exercise. It is the gold standard measure of aerobic/cardiovascular fitness.", marks: 2, hint: "The maximum oxygen uptake capacity — the key measure of aerobic fitness", acceptedAnswers: ["maximum volume of oxygen the body can use per minute", "max oxygen uptake per kg per minute", "maximum oxygen consumption during exercise", "measure of aerobic fitness / maximum oxygen uptake"] },
    { question: "Name the three classes of lever and give one sporting example of each.", answer: "First class lever: fulcrum between effort and load (e.g. head nodding — neck muscles lift the skull). Second class lever: load between fulcrum and effort (e.g. standing on tiptoe — ankle joint). Third class lever: effort between fulcrum and load (most common in the body — e.g. bicep curl at the elbow).", marks: 3, hint: "First: seesaws and nodding. Second: tiptoes. Third: most body movements including bicep curls.", acceptedAnswers: ["first class: fulcrum between effort and load (nodding); second class: load between fulcrum and effort (tiptoe); third class: effort between fulcrum and load (bicep curl)", "1st: nodding head / 2nd: standing on tiptoe / 3rd: bicep curl"] },
    { question: "What is 'DOMS' and when does it occur?", answer: "DOMS stands for Delayed Onset Muscle Soreness — the muscle pain and stiffness felt 24–72 hours after intense or unaccustomed exercise. Caused by microscopic tears in muscle fibres during eccentric contractions. It is a normal part of muscle adaptation.", marks: 2, hint: "The muscle soreness felt 1–3 days after a hard workout — Delayed Onset Muscle Soreness", acceptedAnswers: ["Delayed Onset Muscle Soreness", "muscle soreness 24-72 hours after exercise", "DOMS: delayed onset muscle soreness occurring 24–72 hours post-exercise", "muscle pain felt 1-3 days after intense exercise due to microscopic tears"] },
    { question: "What is the 'inverted-U theory' in sports psychology?", answer: "The inverted-U theory (Yerkes-Dodson) proposes that performance improves as arousal increases up to an optimal point, then decreases if arousal becomes too high. Performance is best at a moderate, optimal level of arousal — the peak of the inverted U.", marks: 2, hint: "Too little arousal = poor performance; too much = also poor performance; the middle is best", acceptedAnswers: ["performance improves with arousal up to an optimal point, then decreases", "optimal arousal gives best performance; too little or too much reduces it", "Yerkes-Dodson: moderate arousal = best performance"] },
    { question: "What is 'somatotype' and name the three types?", answer: "Somatotype is the classification of body type. Ectomorph: tall, thin, low muscle and fat. Mesomorph: muscular, broad shoulders, low body fat — ideal athletic build. Endomorph: wide hips, high body fat, rounder build.", marks: 3, hint: "The three body types: ectomorph (thin), mesomorph (muscular), endomorph (larger)", acceptedAnswers: ["ectomorph, mesomorph, endomorph", "classification of body type: ectomorph (thin), mesomorph (muscular), endomorph (wider)", "three body types: ectomorph mesomorph endomorph"] },
    { question: "What is the difference between isotonic and isometric muscle contractions?", answer: "Isotonic contractions: the muscle changes length as it contracts. Concentric isotonic — muscle shortens (e.g. bicep curling a weight up). Eccentric isotonic — muscle lengthens under tension (e.g. lowering the weight). Isometric contractions: the muscle contracts but does not change length (e.g. holding a squat position).", marks: 2, hint: "Isotonic = movement; isometric = no movement (holding a position)", acceptedAnswers: ["isotonic = muscle changes length; isometric = muscle does not change length", "isotonic involves movement; isometric is a static contraction", "isotonic: concentric (shortens) or eccentric (lengthens); isometric: no length change"] },
    { question: "Name the three planes of movement.", answer: "Sagittal plane: divides the body into left and right halves — movements forward and back (flexion, extension, e.g. running). Frontal/coronal plane: divides into front and back — movements side to side (abduction, adduction, e.g. star jump). Transverse/horizontal plane: divides into upper and lower — rotational movements (e.g. golf swing).", marks: 3, hint: "Sagittal (front/back), Frontal (side to side), Transverse (rotation)", acceptedAnswers: ["sagittal, frontal, transverse", "sagittal (flexion/extension), frontal (abduction/adduction), transverse (rotation)", "sagittal plane, frontal/coronal plane, transverse/horizontal plane"] },
    { question: "What does 'specificity' mean as a principle of training?", answer: "Specificity means training must be relevant and appropriate to the sport or goal. The body adapts specifically to the demands placed on it. A sprinter should train anaerobically; a marathon runner should train aerobically.", marks: 2, hint: "Train for the specific demands of your sport — a sprinter shouldn't just run marathons", acceptedAnswers: ["training must match the demands of the sport", "the body adapts specifically to the type of training performed", "train for the specific requirements of your sport or goal"] },
    { question: "What is 'interval training'?", answer: "Interval training alternates between periods of intense work and rest/recovery. E.g. 30 seconds maximum sprint, 90 seconds rest, repeated 8 times. Trains both aerobic and anaerobic systems depending on the work-to-rest ratio.", marks: 2, hint: "Alternating between hard work and rest — used by sprinters and many other athletes", acceptedAnswers: ["alternating periods of intense work and rest", "work-rest intervals repeated multiple times", "periods of high intensity followed by rest, e.g. sprint then recover"] },
    { question: "What is the role of haemoglobin?", answer: "Haemoglobin is the iron-containing protein in red blood cells that carries oxygen from the lungs to the working muscles and carries carbon dioxide back to the lungs for removal.", marks: 2, hint: "The protein in red blood cells that carries oxygen around the body", acceptedAnswers: ["carries oxygen from lungs to muscles", "transports oxygen in red blood cells", "haemoglobin carries O2 to muscles and CO2 back to lungs", "iron-containing protein in red blood cells that transports oxygen"] },
    { question: "What is 'commercialisation' in sport and give one positive and one negative effect?", answer: "Commercialisation is the process by which sport becomes associated with business, sponsorship and the generation of profit. Positive: increased funding for athletes and facilities. Negative: smaller sports receive less coverage and funding.", marks: 2, hint: "Sport becoming a commercial product — sponsorship, TV rights, merchandise. Consider both advantages and disadvantages.", acceptedAnswers: ["sport linked to business/sponsorship; positive: more funding; negative: smaller sports ignored", "positive: more money for athletes; negative: sport changed for TV/sponsors", "commercialisation = sport generating profit; + increased funding; - smaller sports get less coverage"] },
    { question: "What is the agonist muscle in a bicep curl?", answer: "The agonist (prime mover) in a bicep curl is the biceps brachii, which contracts concentrically to flex the elbow joint. The antagonist is the triceps brachii, which relaxes and lengthens to allow the movement.", marks: 2, hint: "The agonist is the main muscle producing the movement; the antagonist opposes it", acceptedAnswers: ["biceps brachii is the agonist; triceps brachii is the antagonist", "bicep is the agonist (prime mover); tricep is the antagonist", "agonist = biceps; antagonist = triceps", "biceps brachii contracts concentrically; triceps relaxes"] },
    { question: "What is 'progressive overload' and why is it important?", answer: "Progressive overload means gradually increasing the demands on the body over time so that adaptations continue. Without it, the body adapts to a fixed stimulus and improvements plateau. Apply by increasing FITT variables.", marks: 2, hint: "Gradually increasing the training demand so the body keeps adapting", acceptedAnswers: ["gradually increasing training demands so the body keeps adapting", "progressively increasing FITT variables to continue improvement", "overloading the body slightly more over time to force continued adaptation", "body adapts to stimulus — must increase demand to keep improving"] },
    { question: "What is 'Fartlek training'?", answer: "Fartlek (Swedish for 'speed play') is a continuous training method where the speed and intensity are varied throughout the session, e.g. jogging then sprinting to a landmark then walking. It challenges both aerobic and anaerobic systems.", marks: 2, hint: "Swedish 'speed play' — continuous exercise with varied intensity", acceptedAnswers: ["continuous training with varied speed and intensity", "Fartlek = speed play; varying effort during a continuous run", "jogging and sprinting alternated during a continuous session", "challenges both aerobic and anaerobic systems through intensity variation"] },
    { question: "Name the four chambers of the heart and their functions.", answer: "Right atrium: receives deoxygenated blood from the body. Right ventricle: pumps deoxygenated blood to the lungs. Left atrium: receives oxygenated blood from the lungs. Left ventricle: pumps oxygenated blood to the body (thickest wall).", marks: 2, hint: "Two atria receive blood; two ventricles pump it — right side receives from body/sends to lungs; left does the reverse", acceptedAnswers: ["right atrium, right ventricle, left atrium, left ventricle", "right atrium receives deoxygenated blood; right ventricle pumps to lungs; left atrium receives oxygenated blood; left ventricle pumps to body", "four chambers: right atrium, right ventricle, left atrium, left ventricle"] },
    { question: "What is the difference between arteries, veins and capillaries?", answer: "Arteries: carry oxygenated blood away from the heart under high pressure; thick muscular walls. Veins: carry deoxygenated blood back to the heart under low pressure; contain valves to prevent backflow. Capillaries: microscopic vessels where gaseous exchange occurs; walls one cell thick.", marks: 3, hint: "Arteries = away from heart; veins = back to heart; capillaries = exchange site", acceptedAnswers: ["arteries carry blood away from heart; veins carry blood back; capillaries allow gas exchange", "arteries: high pressure, thick walls; veins: low pressure, valves; capillaries: exchange", "arteries away from heart, veins to heart, capillaries one cell thick for gas exchange"] },
    { question: "What is 'tidal volume' and how does it change during exercise?", answer: "Tidal volume is the volume of air inhaled or exhaled in one breath. At rest it is approximately 0.5 litres. During exercise, tidal volume increases (along with breathing rate) to supply more oxygen and remove carbon dioxide more rapidly.", marks: 2, hint: "Volume of air per breath — how does it change when exercising hard?", acceptedAnswers: ["volume of air inhaled or exhaled per breath", "tidal volume is about 0.5L at rest and increases during exercise", "air per breath; increases during exercise to supply more O2", "tidal volume increases during exercise along with breathing rate"] },
    { question: "What does the acronym SMART stand for in goal-setting?", answer: "Specific (clearly defined goal), Measurable (can be quantified), Achievable (realistic), Relevant (appropriate to the performer), Time-bound (has a deadline). SMART goals improve motivation and focus in training.", marks: 2, hint: "Five criteria for effective goals — Specific, Measurable, Achievable, Relevant, Time-bound", acceptedAnswers: ["Specific, Measurable, Achievable, Relevant, Time-bound", "specific measurable achievable relevant time-bound", "S=specific, M=measurable, A=achievable, R=relevant, T=time-bound", "SMART goal setting: specific, measurable, achievable, relevant, time-bound"] },
    { question: "What is 'muscle hypertrophy'?", answer: "Muscle hypertrophy is the increase in the size (cross-sectional area) of individual muscle fibres, resulting in larger, stronger muscles. It occurs as a long-term adaptation to resistance/weight training, particularly affecting fast-twitch fibres.", marks: 2, hint: "The increase in muscle size from strength training — a long-term training adaptation", acceptedAnswers: ["increase in size of muscle fibres from resistance training", "muscles grow larger through hypertrophy after weight training", "enlargement of muscle fibres as adaptation to strength training", "increase in cross-sectional area of muscle fibres"] },
    { question: "What are the main energy systems used during a 100m sprint?", answer: "The ATP-PC (phosphocreatine) system is the primary energy source — it provides immediate, high-power energy without oxygen for approximately 10 seconds. No lactic acid is produced. It is anaerobic and alactic.", marks: 2, hint: "Immediate, explosive energy — no oxygen, no lactic acid, very short duration", acceptedAnswers: ["ATP-PC (phosphocreatine) system", "anaerobic alactic system using phosphocreatine", "ATP-PC system: immediate energy, no oxygen, no lactic acid, lasts ~10 seconds", "phosphocreatine system for explosive 10-second energy"] },
    { question: "What is 'abduction' and 'adduction' in joint movement?", answer: "Abduction is movement of a limb away from the midline of the body (e.g. raising the arm out to the side). Adduction is movement towards the midline (e.g. lowering the arm back to the body). These occur in the frontal plane.", marks: 2, hint: "Ab = away; Ad = towards. Think of ABduction = ABaway from the midline", acceptedAnswers: ["abduction = away from midline; adduction = towards midline", "abduction moves limb out from body; adduction brings it back in", "abduction: arm raised sideways; adduction: arm lowered back to side", "away from midline vs towards midline"] },
    { question: "What is 'self-efficacy' in sports psychology?", answer: "Self-efficacy (Bandura) is a performer's belief in their own ability to succeed in a specific task. High self-efficacy leads to better performance, greater persistence and confidence. Built through: mastery experiences, vicarious experience, verbal persuasion, physiological interpretation.", marks: 2, hint: "Bandura's concept — belief in your own ability to succeed at a specific task", acceptedAnswers: ["self-efficacy is a performer's belief in their ability to succeed", "Bandura: self-efficacy = belief in own ability for a specific task", "confidence in one's ability to perform a specific task successfully", "high self-efficacy improves performance and persistence"] },
    { question: "What are the effects of anabolic steroids on sports performance and why are they banned?", answer: "Anabolic steroids are synthetic hormones that increase muscle protein synthesis, leading to greater muscle mass and strength, faster recovery, and increased aggression. They are banned because they create an unfair advantage and have serious health risks: liver damage, cardiovascular disease, hormonal disruption, stunted growth in adolescents.", marks: 2, hint: "Muscle-building drugs — performance benefits and serious health/ethical risks", acceptedAnswers: ["increase muscle mass and strength; banned for health risks and unfair advantage", "anabolic steroids = synthetic hormones boosting muscle growth; banned due to health risks", "increase protein synthesis for more muscle; banned: liver damage, heart disease, unfair", "performance: more muscle, faster recovery; risks: liver damage, hormonal issues, cardiovascular disease"] },
    { question: "What is the 'reversibility' principle of training?", answer: "Reversibility (also called detraining) means that if training stops, the fitness adaptations gained will be lost. Aerobic fitness can decline within 2–4 weeks of inactivity. Maintaining fitness requires consistent training.", marks: 2, hint: "Use it or lose it — fitness gains reverse when training stops", acceptedAnswers: ["fitness adaptations are lost if training stops", "reversibility = use it or lose it", "detraining: fitness declines when training ceases", "aerobic fitness decreases within 2-4 weeks without training"] },
    { question: "Name three fitness tests and what they measure.", answer: "1. Multi-stage fitness test (bleep test): measures cardiovascular endurance/VO2 max. 2. Grip dynamometer: measures muscular strength. 3. Sit-and-reach test: measures flexibility at the hamstrings/lower back. Others: Illinois agility run (agility), standing broad jump (power), 30m sprint (speed).", marks: 3, hint: "Match each test to the fitness component it measures", acceptedAnswers: ["bleep test = cardiovascular endurance; grip dynamometer = strength; sit-and-reach = flexibility", "multi-stage fitness test, grip dynamometer, sit-and-reach", "bleep test (VO2 max), sit and reach (flexibility), grip dynamometer (strength)", "three tests: bleep test, sit-and-reach, standing broad jump"] },
    { question: "What is 'circuit training' and what are its benefits?", answer: "Circuit training involves a series of exercises performed at different stations with minimal rest between exercises. Each station targets a different muscle group or fitness component. Benefits: improves muscular endurance, cardiovascular fitness, strength; time-efficient; easily adaptable for different fitness goals and group sizes.", marks: 2, hint: "Stations of different exercises — highly adaptable training method", acceptedAnswers: ["series of exercises at stations with minimal rest; improves muscular endurance and cardiovascular fitness", "circuit: different exercise stations; benefits: muscular endurance, CV fitness, adaptable", "rotating through exercise stations targeting different muscles; improves endurance and strength", "circuit training uses stations; benefits include adaptability and muscular endurance"] },
    { question: "What is 'attribution theory' in sports psychology?", answer: "Attribution theory (Weiner's model) explains how performers interpret the causes of their success or failure. Attributions are classified by: locus of causality (internal/external) and stability (stable/unstable). E.g. attributing failure to lack of effort (internal, unstable) is healthier than blaming low ability (internal, stable).", marks: 2, hint: "Weiner's model — how athletes explain success and failure (internal/external, stable/unstable)", acceptedAnswers: ["Weiner's model explains how performers attribute causes of success or failure", "attribution: internal/external and stable/unstable dimensions", "performers interpret success/failure as internal or external, stable or unstable", "attribution theory by Weiner: locus of causality and stability dimensions"] },
    { question: "What is the difference between 'power' and 'strength' as fitness components?", answer: "Strength is the maximum force a muscle or group of muscles can exert in a single maximal contraction. Power is the ability to exert maximum force in the shortest possible time (Power = Strength × Speed). A weightlifter needs strength; a sprinter or jumper needs power.", marks: 2, hint: "Strength = maximum force; power adds speed to that force", acceptedAnswers: ["strength = maximum force in one contraction; power = strength × speed", "power combines strength and speed; strength is maximum force alone", "strength: max force; power: force × speed (explosive)", "power = strength × speed; strength is max force in a single contraction"] },
    { question: "What are the three axes of rotation used in movement analysis?", answer: "Longitudinal axis: runs top to bottom through the body — rotation movements (e.g. pirouette in ice skating, spinning in gymnastics). Transverse/frontal axis: runs side to side — forward/backward rotations (e.g. somersault, cycling). Sagittal axis: runs front to back — cartwheel movements.", marks: 3, hint: "Three axes running through the body — match each to a sport rotation movement", acceptedAnswers: ["longitudinal, transverse, sagittal axes", "longitudinal (spin/pirouette), transverse (somersault), sagittal (cartwheel)", "longitudinal axis = spinning; transverse axis = somersault; sagittal axis = cartwheel", "three axes: longitudinal runs top-bottom, transverse side-side, sagittal front-back"] },
    { question: "What are the signs and symptoms of dehydration during exercise?", answer: "Signs of dehydration: thirst, dark urine, headache, dizziness, reduced concentration, muscle cramps, reduced performance. Severe dehydration causes heat exhaustion and heat stroke. Even 2% body weight lost as fluid reduces performance by up to 20%.", marks: 2, hint: "What happens to the body and performance when fluid is not replaced during exercise?", acceptedAnswers: ["thirst, dark urine, headache, dizziness, muscle cramps, reduced performance", "dehydration signs: thirst, headache, reduced concentration, dark urine", "2% fluid loss reduces performance; signs include thirst, dizziness, cramps", "thirst, dizziness, cramps, dark urine, headache, reduced performance"] },
    { question: "What is 'plyometric training' and which fitness component does it develop?", answer: "Plyometric training uses explosive exercises like box jumps, bounding, and depth jumps that rapidly stretch then shorten muscles (the stretch-shortening cycle). It primarily develops muscular power (strength × speed) and is used by sprinters, jumpers and team sport players.", marks: 2, hint: "Explosive jump exercises using the stretch-shortening cycle — develops power", acceptedAnswers: ["explosive jump training using the stretch-shortening cycle; develops muscular power", "plyometrics: box jumps, depth jumps; develops power (strength × speed)", "plyometric training uses rapid stretch and shorten of muscles to develop power", "depth jumps and bounding develop muscular power through plyometrics"] },
    { question: "What is EPO and why is it used as a performance-enhancing drug?", answer: "EPO (erythropoietin) is a hormone that stimulates the production of red blood cells. Athletes use it to increase oxygen-carrying capacity (more haemoglobin), improving aerobic performance and endurance. It is banned because it creates unfair advantage and blood thickening increases risk of stroke and heart attack.", marks: 2, hint: "Hormone increasing red blood cells to carry more oxygen — used by endurance athletes", acceptedAnswers: ["EPO increases red blood cell production and oxygen-carrying capacity", "erythropoietin: more red blood cells = more oxygen delivered to muscles", "EPO boosts aerobic endurance by increasing haemoglobin; banned due to stroke risk", "increases red blood cells and oxygen delivery; banned for health risks and unfair advantage"] },
    { question: "Name four major muscles of the lower body and their primary action.", answer: "Quadriceps (front of thigh): knee extension. Hamstrings (back of thigh): knee flexion. Gluteus maximus (buttock): hip extension. Gastrocnemius (calf): plantar flexion (pointing the foot). These muscles are active during running, cycling and jumping.", marks: 3, hint: "Four muscles below the waist — name each and what movement they produce", acceptedAnswers: ["quadriceps (knee extension), hamstrings (knee flexion), gluteus maximus (hip extension), gastrocnemius (plantar flexion)", "quads extend knee, hamstrings flex knee, glutes extend hip, gastrocnemius points foot", "quadriceps, hamstrings, gluteus maximus, gastrocnemius with their actions", "quadriceps = knee extension; hamstrings = knee flexion; glutes = hip extension; calf = plantar flexion"] },
    { question: "What is meant by 'cardiovascular endurance'?", answer: "Cardiovascular endurance (also called aerobic endurance) is the ability of the heart, lungs, and circulatory system to supply oxygen to the working muscles over a prolonged period of exercise. It is measured by VO2 max and is critical for events like marathon running and cycling.", marks: 2, hint: "The heart and lungs' ability to sustain oxygen delivery during long exercise", acceptedAnswers: ["ability of the heart, lungs and circulation to supply oxygen during prolonged exercise", "cardiovascular endurance = sustained aerobic performance; measured by VO2 max", "the ability to sustain aerobic exercise over a long period", "heart lungs and blood vessels efficiently delivering oxygen during sustained activity"] },
    { question: "What is the difference between 'intrinsic' and 'extrinsic' motivation in sport?", answer: "Intrinsic motivation comes from within — the enjoyment, personal satisfaction, challenge, and love of the sport itself. Extrinsic motivation comes from external rewards — trophies, medals, prize money, praise, fame. Intrinsic motivation is generally more sustainable long-term.", marks: 2, hint: "Internal desire vs external rewards — which sustains motivation longer?", acceptedAnswers: ["intrinsic = internal (enjoyment/satisfaction); extrinsic = external (trophies/prizes)", "intrinsic from within; extrinsic from external rewards like medals", "intrinsic motivation from enjoyment; extrinsic from rewards and recognition", "internal vs external motivation; intrinsic more sustainable"] },
    { question: "What is the function of the synovial fluid in a joint?", answer: "Synovial fluid is a thick, viscous fluid secreted by the synovial membrane inside a joint capsule. Its function is to lubricate the joint, reducing friction between articular cartilage surfaces, and to provide nutrients to the articular cartilage which has no blood supply.", marks: 2, hint: "The fluid inside a joint — what does it do to help smooth movement?", acceptedAnswers: ["lubricates the joint reducing friction", "synovial fluid reduces friction between cartilage surfaces in a joint", "lubricates and nourishes the articular cartilage", "secreted by synovial membrane; lubricates joint and reduces friction"] },
    { question: "What is 'blood pressure' and what happens to it during exercise?", answer: "Blood pressure is the force of blood pressing against the walls of arteries. It is measured as systolic (pressure during heart contraction) over diastolic (pressure during relaxation), e.g. 120/80 mmHg. During exercise, blood pressure rises as cardiac output increases.", marks: 2, hint: "Force of blood on artery walls — measured as systolic/diastolic; what happens during exercise?", acceptedAnswers: ["force of blood on artery walls; rises during exercise as cardiac output increases", "blood pressure = systolic/diastolic; increases during exercise", "measured as systolic over diastolic; exercise raises blood pressure", "120/80 mmHg at rest; rises during exercise as heart pumps harder"] },
    { question: "Name the three types of synovial joint found in the body.", answer: "Ball and socket: greatest range of movement — flexion, extension, abduction, adduction, rotation (hip, shoulder). Hinge: flexion and extension only (knee, elbow). Pivot: rotation only (radius rotating around ulna at the radioulnar joint; atlas and axis in the neck).", marks: 3, hint: "Three types from most to least movement range — ball and socket, hinge, pivot", acceptedAnswers: ["ball and socket (hip/shoulder), hinge (knee/elbow), pivot (radioulnar/neck)", "ball and socket, hinge, pivot", "ball and socket: most movement; hinge: flex/extend only; pivot: rotation only"] },
    { question: "What is 'flexibility' and why is it important in sport?", answer: "Flexibility is the range of motion available at a joint, determined by the elasticity of muscles, tendons, and ligaments. It is important because: it reduces injury risk, improves technique and movement efficiency, aids recovery, and is directly necessary in sports like gymnastics and swimming.", marks: 2, hint: "Range of motion at a joint — why does it matter for sport and injury prevention?", acceptedAnswers: ["range of motion available at a joint", "flexibility is the range of movement at a joint; reduces injury risk and improves technique", "determined by elasticity of muscles and tendons; reduces injury and aids performance", "range of movement at joint; important for injury prevention and sports like gymnastics"] },
    { question: "What does 'agility' mean as a fitness component and give a sporting example?", answer: "Agility is the ability to change direction quickly and accurately while maintaining balance and control. It requires a combination of speed, strength, coordination and balance. Sporting examples: a rugby player sidestepping a tackle; a tennis player changing direction to reach a shot.", marks: 2, hint: "Changing direction quickly with control — a key skill for team sports and racket sports", acceptedAnswers: ["ability to change direction quickly and accurately", "agility = changing direction with speed and control", "e.g. rugby player sidestepping, tennis player changing direction quickly", "fast direction change with balance; e.g. basketball player evading a defender"] },
  ],
  mid: [
    { question: "Explain how training principles (FITT) should be applied to improve cardiovascular fitness.", answer: "FITT: Frequency — how often you train (3–5 sessions/week for cardiovascular improvement). Intensity — measured by heart rate as percentage of maximum (60–80% for aerobic fitness; 220 − age = max HR). Time — minimum 20 minutes per session for cardiovascular benefit. Type — continuous activity: running, cycling, swimming. Without progressive overload — gradually increasing FITT — the body adapts and improvements plateau.", marks: 4, hint: "Define each component of FITT and explain how each relates specifically to cardiovascular training", acceptedAnswers: ["frequency 3-5 per week, intensity 60-80% max HR, time 20+ minutes, type aerobic activity", "increase frequency, train at 60-80% max heart rate, 20+ minutes, running/cycling/swimming"] },
    { question: "Analyse the physical and psychological effects of a warm-up before exercise.", answer: "Physical effects: Increased heart rate and blood flow delivering more oxygen to muscles. Raised muscle temperature improves enzyme activity and contraction speed. Increased flexibility and range of motion reduces injury risk. Gradual increase in breathing rate prepares the respiratory system. Synovial fluid lubricates joints. Psychological effects: Mental preparation and focus; reduces pre-competition anxiety; activates arousal to optimal level (inverted-U theory); rehearsal of skills builds confidence and reduces errors.", marks: 4, hint: "Cover at least 3 physical effects and 2 psychological effects. Use physiological language.", acceptedAnswers: ["physical: increased HR, raised muscle temperature, increased flexibility, synovial fluid / psychological: focus, reduces anxiety", "heart rate up, muscles warmer, more flexible, less injury risk; psychological: reduces anxiety, mental focus"] },
    { question: "Explain the three types of muscle contraction (concentric, eccentric, isometric) with a sporting example of each.", answer: "Concentric contraction: the muscle shortens as it generates force. Example: the quadriceps shorten concentrically during the upward phase of a squat. Eccentric contraction: the muscle lengthens under tension, acting as a brake. Example: the quadriceps contract eccentrically during the downward phase of a squat. Isometric contraction: the muscle generates force without changing length. Example: a gymnast holding an iron cross position.", marks: 4, hint: "Define each type, name the muscle and describe the movement direction for each sporting example", acceptedAnswers: ["concentric: muscle shortens (squat up/bicep curl); eccentric: muscle lengthens under tension (squat down); isometric: no length change (holding position)", "concentric shortens muscle; eccentric lengthens muscle; isometric no movement"] },
    { question: "Explain what the 'components of fitness' are and how they are categorised.", answer: "Health-related components (relate to overall health): cardiovascular endurance; muscular strength; muscular endurance; flexibility; body composition. Skill-related components (relate to sports performance): agility; balance; coordination; power; reaction time; speed. Some sports require multiple components — a basketball player needs speed, agility, coordination and cardiovascular endurance.", marks: 5, hint: "Categorise clearly into health-related and skill-related. Define each component briefly and give a sporting example.", acceptedAnswers: ["health-related: cardiovascular endurance, muscular strength, muscular endurance, flexibility, body composition / skill-related: agility, balance, coordination, power, reaction time, speed", "CV endurance, muscular strength, muscular endurance, flexibility, body composition (health); agility, balance, coordination, power, reaction time, speed (skill)"] },
    { question: "Describe the long-term effects of regular aerobic exercise on the cardiovascular system.", answer: "Cardiac hypertrophy: the heart muscle grows stronger and larger. Increased stroke volume: the heart pumps more blood per beat. Lower resting heart rate (bradycardia): trained athletes have resting heart rates as low as 40 bpm. Increased capillarisation around muscle fibres. Reduced resting blood pressure. Lower risk of cardiovascular disease long-term.", marks: 5, hint: "Cover at least four long-term adaptations: cardiac hypertrophy, stroke volume, resting heart rate, capillarisation, blood pressure", acceptedAnswers: ["cardiac hypertrophy, increased stroke volume, lower resting heart rate (bradycardia), increased capillarisation", "heart becomes larger and stronger, stroke volume increases, resting HR decreases, more capillaries"] },
    { question: "Explain the barriers to participation in sport for different groups in society and how they might be overcome.", answer: "Women: media coverage unequal; stereotyping. Strategies: equal coverage, role models, equal prize money. Ethnic minorities: cultural barriers, stereotyping. Strategies: targeted initiatives, diverse role models. Disabled people: lack of accessible facilities. Strategies: Paralympic media coverage, facility investment. Socioeconomic barriers: cost of equipment, membership. Strategies: National Lottery funding, free facilities.", marks: 5, hint: "Cover at least three different groups. For each: identify the barrier type and suggest a realistic strategy to overcome it", acceptedAnswers: ["women: stereotyping, unequal media; ethnic minorities: cultural barriers; disabled: inaccessible facilities; socioeconomic: cost", "barriers for women, disabled, low income; overcome by funding, role models, inclusive facilities"] },
    { question: "Explain the components of the respiratory system and describe what happens during gaseous exchange.", answer: "Air enters through the nasal cavity/mouth, passes down the trachea, into the bronchi, then bronchioles, ending in the alveoli. Gaseous exchange occurs at the alveoli: oxygen diffuses into the blood (where it binds to haemoglobin). Carbon dioxide diffuses from blood to alveolus and is exhaled. Driven by concentration gradients. During exercise: breathing rate and tidal volume increase.", marks: 5, hint: "Trace the pathway of air. Explain diffusion across the alveoli using concentration gradients. Describe how exercise changes breathing.", acceptedAnswers: ["air travels: nasal cavity → trachea → bronchi → bronchioles → alveoli; O2 diffuses into blood, CO2 diffuses out, driven by concentration gradients", "trachea → bronchi → bronchioles → alveoli; oxygen into blood, carbon dioxide out; breathing rate increases during exercise"] },
    { question: "Describe three training methods suitable for developing different components of fitness, explaining what each trains and how.", answer: "Interval training: alternates work and rest. Trains anaerobic fitness and cardiovascular endurance depending on work-to-rest ratio. Plyometric training: explosive jump/landing exercises. Trains muscular power using the stretch-shortening cycle. Circuit training: a series of exercises at stations, each targeting different muscle groups. Can train muscular endurance, cardiovascular endurance and strength. Each method must follow FITT and progressive overload.", marks: 5, hint: "Name three distinct methods, explain the mechanism of each, name the fitness component(s) targeted, and describe how to apply it", acceptedAnswers: ["interval training (aerobic/anaerobic), plyometric training (power), circuit training (endurance/strength)", "interval: work-rest periods for aerobic or anaerobic; plyometrics uses stretch-shortening cycle for power; circuit training targets multiple components"] },
    { question: "What is the 'inverted-U theory' and how should a sports coach use this knowledge practically?", answer: "The inverted-U theory shows that performance improves as arousal increases up to an optimal point, then declines. Optimal arousal varies by sport: complex, fine motor skill sports require lower arousal; gross motor, explosive sports tolerate higher arousal. Coaches: increase arousal through energetic warm-ups, motivational talk, music. Reduce arousal through breathing exercises, mental rehearsal, positive self-talk.", marks: 5, hint: "Define the theory with its curve shape. Explain optimal levels for different sports. Give specific strategies coaches use to raise and lower arousal.", acceptedAnswers: ["performance increases with arousal to an optimal point then decreases; coaches raise arousal (music, motivation) or lower it (breathing, imagery)", "optimal arousal differs by sport: golf needs low; sprinting tolerates high; coach controls arousal level"] },
    { question: "Explain the role of the ATP-PC, lactic acid and aerobic energy systems during different types of exercise.", answer: "ATP-PC system: provides immediate high-power energy for approximately 10 seconds without oxygen. No lactic acid produced. Used in 100m sprint, maximum weight lift. Lactic acid system: produces ATP rapidly for 30 seconds to 2 minutes without oxygen; lactic acid accumulates causing fatigue. Used in 400m running, 100m swimming. Aerobic system: uses oxygen to produce ATP from glucose/fats; can sustain exercise for hours; produces CO2 and water. Used in marathon running, cycling. All three systems contribute simultaneously, with the dominant system determined by exercise intensity and duration.", marks: 4, hint: "Name all three systems, state the duration and oxygen use of each, and give a sporting example", acceptedAnswers: ["ATP-PC: immediate 10 seconds, no oxygen; lactic acid: 30s-2min, no oxygen, lactic acid; aerobic: oxygen, long duration", "ATP-PC for sprint, lactic acid for 400m, aerobic for marathon; anaerobic vs aerobic", "three systems: alactic anaerobic (ATP-PC), lactic anaerobic, aerobic; different durations and intensities"] },
    { question: "Explain how a cool-down helps the body recover after exercise.", answer: "A cool-down involves gradually reducing exercise intensity (e.g. slow jog to walk). Benefits: prevents blood pooling in the muscles (which can cause dizziness) by keeping blood circulating; removes lactic acid from muscles; keeps breathing and heart rate elevated briefly to continue O2 delivery; maintains muscle temperature and pliability to reduce DOMS risk. Stretching during cool-down maintains/improves flexibility when muscles are warm.", marks: 4, hint: "Explain the physiological reasons why cooling down gradually is better than stopping suddenly", acceptedAnswers: ["prevents blood pooling, removes lactic acid, gradually reduces HR and breathing rate, reduces DOMS risk", "cool-down prevents dizziness by maintaining circulation; removes lactic acid; reduces DOMS", "gradually reduces HR; prevents blood pooling; lactic acid removed; stretching maintains flexibility"] },
    { question: "Analyse how socioeconomic status affects participation in sport in the UK.", answer: "Cost barriers: equipment, club membership, travel, coaching are expensive. Lower income households cannot afford them. Time: long working hours reduce time for sport. Facility access: poorer areas often have fewer/worse sports facilities. Schools: underfunded schools in deprived areas have less PE provision. Strategies: School Sport Premium funding, National Lottery sport grants, free public leisure facilities. Evidence: children from higher-income families are 2× more likely to participate in organised sport.", marks: 4, hint: "Cover cost, time, facilities, school provision. Give specific strategies and evidence of inequality", acceptedAnswers: ["cost of equipment and membership; lack of time; poor facilities in deprived areas; underfunded schools", "socioeconomic barriers: cost, time, access to facilities; overcome by lottery funding and subsidised sport", "lower income = less participation; barriers include cost, time, facility access; strategies: lottery funding, school sport premium"] },
    { question: "Explain what 'mental rehearsal' (imagery) is and how it helps sports performance.", answer: "Mental rehearsal (imagery/visualisation) involves mentally picturing the performance of a skill or event in as much detail as possible, without physically performing it. It activates similar neural pathways to physical practice. Benefits: builds confidence; reduces anxiety by familiarising the performer with the situation; reinforces technique and decision-making patterns; helps with pre-competition arousal regulation. Used widely in elite sport — e.g. Olympic divers visualise each dive before stepping onto the board.", marks: 4, hint: "Define mental rehearsal, explain the neural mechanism, and give specific performance benefits with an example", acceptedAnswers: ["mentally picturing the performance activating similar neural pathways to physical practice", "imagery = visualising performance in detail; reduces anxiety, builds confidence, reinforces technique", "mental rehearsal activates similar brain patterns to real practice; improves confidence and technique", "visualising performance before competing; used by elite athletes to reduce anxiety and improve focus"] },
    { question: "Describe the structure and function of the skeleton, distinguishing between the axial and appendicular skeleton.", answer: "The skeleton has five functions: support (framework for the body), protection (skull protects brain; ribcage protects heart and lungs), movement (bones act as levers for muscles), blood cell production (red and white blood cells produced in red bone marrow), and mineral storage (calcium and phosphorus stored in bone). Axial skeleton: central core — skull, vertebral column, ribcage (80 bones). Appendicular skeleton: limbs and girdles — arms, legs, shoulder girdle, pelvic girdle (126 bones). Types of bone: long (femur, humerus — movement), short (carpals, tarsals — precision), flat (skull, scapula — protection), irregular (vertebrae), sesamoid (patella — protects tendons).", marks: 5, hint: "List 5 functions. Define axial vs appendicular with examples. Name bone types with examples.", acceptedAnswers: ["axial: skull, vertebral column, ribcage; appendicular: limbs and girdles", "functions: support, protection, movement, blood cell production, mineral storage", "axial skeleton = central core; appendicular = limbs; five functions of the skeleton", "long, short, flat, irregular, sesamoid bones with examples"] },
    { question: "Explain how a sport performer's diet should differ from a non-active person. Focus on carbohydrates, protein, and hydration.", answer: "Carbohydrates: athletes need more carbohydrates as their primary fuel source, especially before and during endurance exercise. Carbohydrate loading (increasing intake 3-5 days before an event) maximises glycogen stores. Protein: athletes need more protein (1.2-2.0g per kg body weight vs 0.8g for non-active adults) for muscle repair and growth, especially after resistance training. Hydration: athletes lose significantly more fluid through sweat and must replace it before, during and after exercise. Even 2% fluid loss reduces performance. Sports drinks provide electrolytes (sodium, potassium) lost in sweat during prolonged exercise.", marks: 4, hint: "For each nutrient: how much more does an athlete need and when? Why specifically?", acceptedAnswers: ["athletes need more carbohydrates for energy, more protein for muscle repair, and more fluid for sweat replacement", "carbohydrate loading before events; higher protein for muscle repair; hydration critical (2% loss reduces performance)", "more carbs (fuel), more protein (repair), more fluids (sweat); specific timing around training"] },
    { question: "Evaluate the role of sport in promoting health and well-being, considering physical, mental and social benefits.", answer: "Physical benefits: reduces risk of cardiovascular disease (regular exercise lowers blood pressure, cholesterol); reduces obesity (energy expenditure); strengthens bones (reduces osteoporosis risk); improves immune function. Mental benefits: exercise releases endorphins (natural mood boosters); reduces symptoms of depression and anxiety; improves sleep quality; provides stress relief; builds self-esteem and self-efficacy. Social benefits: team sport develops social skills, communication, trust, and teamwork; provides community belonging; introduces positive peer relationships; reduces social isolation (particularly beneficial for elderly populations). Evaluation: regular physical activity is one of the most evidence-based public health interventions available — the NHS recommends 150 minutes moderate activity per week for adults.", marks: 5, hint: "Give at least two examples in each category (physical, mental, social). Use evidence or recommendations where possible.", acceptedAnswers: ["physical: reduces CVD risk, obesity, improves bone density; mental: endorphins, reduces depression; social: teamwork, community belonging", "physical health benefits (heart, weight, bones); mental benefits (endorphins, self-esteem); social benefits (teamwork, belonging)", "sport improves physical health, mental wellbeing (endorphins) and social connections"] },
    { question: "Describe the impact of technology on sport performance and participation.", answer: "Technology in performance: video analysis allows frame-by-frame breakdown of technique; GPS tracking monitors distance, speed, and work rate in training; heart rate monitors allow precise intensity control; altitude tents simulate high-altitude training to boost red blood cell production. Equipment: carbon fibre running shoes, aerodynamic cycling helmets and skin suits, swimsuits (FINA regulations). Officiating: Hawk-Eye (cricket, tennis line calls), VAR (football), goal-line technology. Participation: fitness apps, wearables, YouTube coaching tutorials, online classes increase access to training. Concerns: technology creates unfair advantage if unequally distributed; technology errors in officiating; deskilling of match officials.", marks: 4, hint: "Cover performance technology, equipment, officiating technology, and participation technology with specific examples", acceptedAnswers: ["video analysis, GPS, heart rate monitors for performance; Hawk-Eye, VAR for officiating; apps for participation", "technology helps performance (GPS, video), officiating (VAR, Hawk-Eye), and participation (apps, wearables)", "carbon fibre equipment, GPS tracking, heart rate monitors, Hawk-Eye, VAR, fitness apps"] },
    { question: "Explain how the principle of 'progressive overload' is applied differently in aerobic training vs resistance training.", answer: "Aerobic training: progressive overload applied by increasing distance, duration, or speed (e.g. adding 10% to weekly mileage). Intensity measured by heart rate percentage (e.g. progressing from 65% to 75% VO2 max). Add more sessions per week (frequency). Resistance training: progressive overload applied by increasing load (weight lifted), volume (sets × reps), or reducing rest periods. 'Rep max' progression: when you can complete 3 sets of 12 with good form, increase load by 5-10%. Concept of progressive overload is identical — the mechanisms differ because the adaptations targeted differ (aerobic vs muscular hypertrophy/strength).", marks: 4, hint: "Explain how overload is measured/applied in aerobic training AND resistance training with specific metrics for each", acceptedAnswers: ["aerobic: increase distance, duration, intensity (% HR max); resistance: increase load, sets, reps", "progressive overload in aerobic = more distance/speed; in resistance = more weight/reps", "aerobic: longer or faster; resistance: heavier weights or more reps/sets; same principle, different application"] },
    { question: "Explain what happens to heart rate and stroke volume during a graded exercise test from rest to maximal effort.", answer: "At rest: heart rate approximately 70 bpm; stroke volume approximately 70ml (cardiac output ~5L/min). As intensity increases: heart rate rises proportionally with exercise intensity (linear relationship). Stroke volume also increases up to approximately 40–60% VO2 max, then plateaus. Cardiac output increases due to both HR and SV rising. At maximal effort: heart rate reaches maximum (220 − age); SV has plateaued; cardiac output is at maximum. Trained athletes have higher stroke volumes at every intensity (allowing same cardiac output at lower HR = bradycardia). Rate of perceived exertion (RPE) and ventilation also increase linearly with intensity.", marks: 4, hint: "Describe changes in both HR and SV from rest to max. Explain why SV plateaus. Compare trained vs untrained responses.", acceptedAnswers: ["HR increases linearly with intensity; SV increases to 40-60% VO2 max then plateaus; cardiac output increases throughout", "heart rate rises proportionally; stroke volume plateaus around 40-60% max intensity; cardiac output = HR × SV", "both HR and SV rise; SV plateaus; HR continues to max (220-age); trained athletes have higher SV"] },
    { question: "Evaluate the use of performance-enhancing drugs in sport, discussing the ethical issues and specific health risks of two named substances.", answer: "Anabolic steroids: increase muscle protein synthesis → greater muscle mass, strength, faster recovery. Health risks: liver damage, cardiovascular disease (enlarged heart, blood clotting), hormonal disruption (testosterone suppression in males, virilisation in females), stunted growth in adolescents, mood disorders ('roid rage'). EPO (erythropoietin): stimulates red blood cell production → more haemoglobin → improved O2 delivery → enhanced aerobic performance. Health risks: blood thickening causing clots, stroke, pulmonary embolism, heart attack — particularly during sleep when heart rate is low. Ethical issues: violates spirit of fair play; those without access are disadvantaged; creates an arms race of doping; pressure on clean athletes to dope to compete. Governance: WADA Anti-Doping Code; UKAD (UK Anti-Doping); in-competition and out-of-competition testing; therapeutic use exemptions (TUEs). Conclusion: performance-enhancing drugs fundamentally undermine the integrity of sport and pose serious, sometimes fatal, health risks — however eradication remains difficult.", marks: 5, hint: "Discuss two specific drugs by name, their performance effects, specific health risks, ethical dimensions, and governance responses", acceptedAnswers: ["anabolic steroids: muscle mass/strength; EPO: red blood cells/endurance; both banned for health risks and fairness", "steroids = liver damage, heart disease, hormonal issues; EPO = blood clots, stroke; both violate fair play", "ethical: unfair advantage, health risks; anabolic steroids and EPO named with specific effects and risks"] },
    { question: "Explain how commercialisation and the media have changed the nature of sport.", answer: "Revenue streams: television rights (Premier League earns £3bn+/season from TV rights), sponsorship, merchandise, advertising. Positive effects: massive increase in funding for elite athletes and facilities; global media exposure grows participation at grassroots level; technology investment improves officiating and performance analysis. Negative effects: sport scheduling changed to suit TV (e.g. late kick-offs, mid-week fixtures affecting fans); smaller sports receive negligible coverage; rule changes to increase entertainment value may harm sporting integrity; wealth inequality between rich and poor clubs/athletes. Satellite/streaming changes access: pay TV reduces free-to-air sport (tennis, cricket, boxing largely behind paywalls). Social media: athletes build personal brands; direct fan interaction; concerns about online abuse of athletes.", marks: 5, hint: "Cover money flows, positive effects on funding/participation, negative effects on sport integrity and access, and the role of social media", acceptedAnswers: ["TV rights, sponsorship generate revenue; positive: funding/global reach; negative: scheduling changes, wealth inequality, smaller sports ignored", "commercialisation brings funding but changes sport to suit TV; social media creates new fan interactions", "positive: funding, technology, global reach; negative: late kick-offs, pay TV, rule changes for entertainment, wealth gaps"] },
  ],
  long: [
    { question: "Evaluate the impact of lifestyle factors on performance and long-term health. Consider diet, rest and the effects of smoking and alcohol. (8 marks)", answer: "Diet: A balanced diet provides energy (carbohydrates), tissue repair (protein), bone health (calcium/vitamin D) and hydration. Poor diet leads to fatigue, injury and chronic disease (obesity, type 2 diabetes, heart disease). Rest: Sleep (7–9 hours/night) when growth hormone is released, muscles repair and glycogen is restored. Overtraining without rest leads to performance decline, injury and burnout. Smoking: Reduces lung capacity and O2 delivery (CO binds haemoglobin); increases heart disease risk; impairs recovery; reduces bone density. Long-term: COPD, lung cancer. Alcohol: Dehydrates; impairs coordination and reaction time; disrupts sleep; adds empty calories; delays recovery; long-term liver and heart disease.", marks: 8, hint: "Cover all four factors. For each: short-term effect on performance + long-term health impact. Conclude with overall evaluation." },
    { question: "Analyse the anatomy of a named joint, explaining the structures involved and how they contribute to movement in a specific sporting activity. (10 marks)", answer: "Example: the knee joint (tibiofemoral joint — synovial hinge joint). Structures: femur and tibia form the joint. Articular cartilage covers both bone surfaces, absorbing shock and reducing friction. Synovial membrane secretes synovial fluid. Joint capsule encloses the joint. Ligaments: medial and lateral collateral ligaments; anterior and posterior cruciate ligaments. Menisci absorb impact. Muscles: quadriceps for extension; hamstrings for flexion. Sport: during running, the knee repeatedly flexes (hamstrings concentrically) and extends (quadriceps concentrically). At footstrike, quadriceps contract eccentrically to absorb impact.", marks: 10, hint: "Identify all structures (bones, cartilage, ligaments, synovial fluid, capsule). Name the muscles and contraction types. Apply specifically to a named sport and describe the movements." },
    { question: "Evaluate the socio-cultural factors that influence participation and performance in sport in the UK. (10 marks)", answer: "Gender: girls drop out of sport at higher rates in adolescence — social pressure, body image, fewer female role models, less media coverage. Strategies: This Girl Can campaign, equal prize money, increased Olympic female events. Ethnicity: underrepresentation in coaching/management; stereotyping. Strategies: targeted initiatives, diverse role models. Social class and economics: participation costs exclude low-income groups. Age: masters' sport growing but elite sport prioritises youth. Disability: barriers — accessible facilities, Paralympic media coverage. Media influence: commercial media shapes which sports receive investment. Overall: multiple intersecting barriers create compounding disadvantage requiring structural interventions.", marks: 10, hint: "Address at least four socio-cultural factors. For each: describe the barrier, give evidence/examples, and evaluate relevant strategies to address it." },
    { question: "How does the body respond and adapt to a long-term training programme? Distinguish between immediate physiological responses and long-term adaptations. (10 marks)", answer: "Immediate responses: Heart rate increases; breathing rate and tidal volume increase; body temperature rises; blood redistributed to working muscles; lactic acid accumulates in anaerobic exercise. Long-term adaptations: Cardiac hypertrophy; increased stroke volume and cardiac output; lower resting heart rate (bradycardia); increased capillary density; increased mitochondria in slow-twitch fibres; muscle hypertrophy after resistance training; increased bone density; increased flexibility with regular stretching. Evaluation: long-term adaptations make the body more efficient — without maintained overload, adaptations reverse (reversibility principle).", marks: 10, hint: "Clearly separate acute (immediate) from chronic (long-term) responses. Cover both cardiovascular and muscular systems." },
    { question: "Evaluate the psychological factors that influence performance in competitive sport, including motivation, anxiety, confidence and mental skills training. (12 marks)", answer: "Motivation: Intrinsic motivation more sustainable than extrinsic. Over-justification effect: excessive extrinsic rewards can undermine intrinsic motivation. Anxiety: Cognitive anxiety (negative thought patterns) and somatic anxiety (physical symptoms). Catastrophe theory: for highly cognitively anxious athletes, small arousal increase causes sudden performance collapse. Self-confidence: Bandura's self-efficacy built through mastery experiences, vicarious experience, verbal persuasion, physiological interpretation. Mental skills: Imagery/visualisation; SMART goal-setting (process goals more controllable than outcome goals); breathing exercises; progressive muscle relaxation; pre-performance routines. Evaluation: psychological preparation considered as important as physical preparation at elite level. Mental skills are trainable.", marks: 12, hint: "Address all four psychological factors. Use theoretical frameworks (inverted-U, catastrophe theory, Bandura's self-efficacy). Give specific mental skills strategies and evaluate their effectiveness." },
    { question: "Evaluate the effectiveness of different training methods for an endurance athlete preparing for a marathon. (10 marks)", answer: "Continuous training: running at a steady moderate intensity (60–70% HR max) for 30–90 minutes. Builds aerobic base, improves cardiac output and capillarisation. Limitation: can become tedious; does not develop speed. Interval training: alternating fast and recovery intervals (e.g. 1km at 85% HR max, 2 min recovery × 8). Develops VO2 max and anaerobic threshold. More time-efficient than continuous. Fartlek training: continuous run with spontaneous intensity variations over varied terrain. Develops both aerobic and anaerobic systems; psychologically engaging. Long runs: weekly long run (20+ miles for marathon training) develops fat oxidation capacity and mental endurance. Periodisation: dividing the 16–20 week preparation into base, build, peak, and taper phases. Base phase emphasises volume; peak phase emphasises quality; taper reduces volume while maintaining intensity to allow recovery before race day. Strength training: 1–2 sessions/week of resistance training improves running economy and reduces injury risk. Nutrition and recovery are equally important: carbohydrate fuelling strategy, sleep, and rest days. Evaluation: no single method is sufficient — effective marathon training combines multiple methods within a periodised plan. The key principles of specificity, progressive overload, and reversibility must guide all training decisions.", marks: 10, hint: "Evaluate at least four training methods specifically for marathon preparation. Include periodisation. Conclude with an overall judgement on what makes an effective programme." },
  ],
  flashcard: [
    { term: "Principle of Overload (FITT)", definition: "For fitness to improve, the body must be stressed beyond its current capacity. Apply FITT: increase Frequency, Intensity, Time or Type. Without overload, the body adapts and plateaus.", example: "Increasing your run from 3km to 5km each session = applying overload" },
    { term: "Aerobic Respiration in Muscles", definition: "Glucose + oxygen → carbon dioxide + water + ATP (energy). Occurs at low to moderate intensity. Uses slow-twitch muscle fibres. Can be sustained long-term. VO2 max measures maximum oxygen uptake capacity.", example: "Marathon running relies almost entirely on aerobic respiration" },
    { term: "Synovial Joint", definition: "A freely moveable joint with synovial fluid (lubricant), joint capsule, articular cartilage, and ligaments (bone to bone). Types: ball and socket (hip, shoulder), hinge (knee, elbow), pivot (neck), gliding (wrist).", example: "The knee is a hinge joint — allows flexion and extension in the sagittal plane" },
    { term: "Components of Fitness", definition: "Health-related: cardiovascular endurance, muscular strength, muscular endurance, flexibility, body composition. Skill-related: agility, balance, coordination, power, reaction time, speed.", example: "A gymnast needs flexibility and balance; a sprinter needs speed and power" },
    { term: "Cardiac Output", definition: "Volume of blood pumped by the heart per minute. CO = Heart Rate × Stroke Volume. Increases during exercise as both HR and SV rise, delivering more oxygen to working muscles.", example: "A trained athlete has a higher stroke volume — same cardiac output at a lower heart rate" },
    { term: "Lactic Acid System", definition: "Anaerobic energy system producing ATP quickly without oxygen. Produces lactic acid as a by-product, causing fatigue. Lasts approximately 30 seconds to 2 minutes. Used in 400m running, 100m swimming.", example: "A 400m runner feels the 'burn' as lactic acid accumulates in the final 100m" },
    { term: "Types of Muscle Fibres", definition: "Type I (slow twitch): aerobic, fatigue-resistant, used for endurance. Type IIa (fast oxidative): moderate speed, some aerobic. Type IIb (fast glycolytic): explosive and fast, fatigue quickly, anaerobic.", example: "Marathon runners have predominantly Type I; sprinters have more Type IIb fibres" },
    { term: "Lever Systems in the Body", definition: "Three classes based on position of fulcrum (joint), effort (muscle) and load (bone + weight). First class: fulcrum between effort and load (nodding). Second class: load between fulcrum and effort (tiptoe). Third class (most common): effort between fulcrum and load (bicep curl).", example: "Third class levers are most common — bicep curl, hamstring curl, throwing" },
    { term: "Inverted-U Theory", definition: "Yerkes-Dodson theory: performance improves with arousal up to an optimal point, then declines. Optimal arousal varies by sport — lower for fine motor skills (golf), higher for gross motor skills (sprinting).", example: "A golfer needs calm focus; a weightlifter benefits from higher arousal" },
    { term: "FITT Principles", definition: "Frequency (how often), Intensity (how hard), Time (how long), Type (what exercise). These variables are manipulated to apply progressive overload and achieve specific training goals.", example: "Increasing frequency from 3 to 5 sessions per week to improve cardiovascular fitness" },
    { term: "Somatotypes", definition: "Body type classifications: Ectomorph (tall, thin, low muscle/fat — distance runners), Mesomorph (muscular, athletic build — sprinters, gymnasts), Endomorph (wider hips, higher body fat — some contact sport athletes).", example: "Most elite sprint cyclists are mesomorphs — high power-to-weight ratio" },
    { term: "Plyometric Training", definition: "Training using explosive jump and landing exercises (box jumps, depth jumps, bounding) that utilise the stretch-shortening cycle. Develops muscular power (strength × speed). Used by sprinters, jumpers and team sport players.", example: "Depth jumps: step off a box, land, then immediately jump as high as possible" },
    { term: "Gaseous Exchange", definition: "At the alveoli: O2 diffuses from air into blood (higher O2 concentration in alveolus); CO2 diffuses from blood into air (higher CO2 in blood). Driven by concentration gradients. O2 binds to haemoglobin for transport.", example: "Exercise increases breathing rate and depth to maintain the concentration gradient" },
    { term: "Intrinsic vs Extrinsic Motivation", definition: "Intrinsic: internal drive — enjoyment, personal satisfaction, mastery. More sustainable long-term. Extrinsic: external rewards — trophies, money, praise. Can undermine intrinsic motivation if overdone (over-justification effect).", example: "A child who loves swimming = intrinsic; a child swimming only for medals = extrinsic" },
    { term: "Planes of Movement", definition: "Sagittal: divides left/right — flexion and extension (running, cycling). Frontal/Coronal: divides front/back — abduction and adduction (star jumps). Transverse/Horizontal: divides upper/lower — rotation (golf swing, discus throw).", example: "A bicep curl occurs in the sagittal plane; a lateral raise in the frontal plane" },
    { term: "Long-term Training Adaptations", definition: "Cardiovascular: cardiac hypertrophy, increased stroke volume, lower resting heart rate (bradycardia), increased capillarisation. Muscular: hypertrophy, increased mitochondria, improved O2 uptake. Skeletal: increased bone density, stronger ligaments and tendons.", example: "An elite endurance athlete may have a resting heart rate of 40 bpm due to cardiac hypertrophy" },
    { term: "ATP-PC Energy System", definition: "Anaerobic alactic system using phosphocreatine to regenerate ATP immediately. Provides maximum power for approximately 10 seconds with no oxygen and no lactic acid production. Replenishes within 2–3 minutes of rest.", example: "100m sprint and a one-rep maximum lift are fuelled almost entirely by the ATP-PC system" },
    { term: "Agonist and Antagonist Muscles", definition: "Agonist (prime mover): the main muscle contracting to produce a movement. Antagonist: the opposing muscle that relaxes and lengthens to allow the movement. They work in pairs. Fixator muscles stabilise the joint.", example: "Bicep curl: biceps brachii = agonist (concentric); triceps brachii = antagonist (relaxes)" },
    { term: "Bradycardia", definition: "Lower-than-average resting heart rate (<60 bpm in trained athletes). A long-term adaptation to aerobic training: the heart becomes more efficient, pumping a larger stroke volume per beat, requiring fewer beats per minute to maintain adequate cardiac output.", example: "Elite cyclists like Lance Armstrong recorded resting heart rates of 32–38 bpm" },
    { term: "SMART Goals", definition: "Goal-setting framework: Specific (clearly defined), Measurable (quantifiable), Achievable (realistic), Relevant (appropriate to performer), Time-bound (has a deadline). SMART process goals improve focus and motivation.", example: "'Run 5km in under 25 minutes within 8 weeks' is SMART; 'get fitter' is not" },
    { term: "Principles of Training (SPORT)", definition: "Specificity (train for your sport's demands), Progressive Overload (gradually increase training stimulus), Reversibility (fitness lost if training stops), Tedium (vary training to maintain motivation), Individual Differences (training must suit the individual).", example: "Reversibility: an injured athlete losing cardiovascular fitness after 2–4 weeks without training" },
    { term: "Weiner's Attribution Model", definition: "Framework for explaining success and failure in sport. Two dimensions: locus of causality (internal = ability/effort; external = task difficulty/luck) and stability (stable = unchanging; unstable = changeable). Athletes who attribute failure to unstable, controllable factors (effort) show healthier responses.", example: "Attributing a loss to lack of effort (internal, unstable) = healthy, motivating attribution" },
    { term: "Blood Pressure and Exercise", definition: "Blood pressure = systolic (heart contracting) / diastolic (heart relaxing), e.g. 120/80 mmHg. During exercise: systolic rises sharply (cardiac output increases); diastolic rises slightly. Long-term aerobic training lowers resting blood pressure.", example: "Elite marathon runner's resting BP may be 110/65; sedentary hypertensive adult may be 140/90" },
    { term: "Barriers to Participation", definition: "Social (stereotyping, peer pressure), cultural (religion, family attitudes), economic (cost of equipment, membership), physical (disability, lack of facilities), psychological (lack of confidence, fear of failure). Strategies: funding, inclusive facilities, role models, campaigns.", example: "This Girl Can campaign addressed social and psychological barriers for women in sport" },
    { term: "Reaction Time and Speed", definition: "Reaction time: the time from stimulus to start of movement response. Speed: the distance covered per unit of time. Both skill-related fitness components. Reaction time improved by anticipation, focus, and practice.", example: "A sprinter's block start depends on minimising reaction time; a 100m time depends on maximum speed" },
    { term: "Commercialisation of Sport", definition: "Sport becoming associated with business, sponsorship and profit generation. TV rights, sponsorship, and merchandise create revenue. Positive: funding for athletes and facilities. Negative: smaller sports get less coverage; sport may change to suit media.", example: "Premier League earns over £3 billion annually from TV rights — funds transfers and wages" },
    { term: "Respiratory System Pathway", definition: "Air pathway: nasal cavity → trachea → bronchi → bronchioles → alveoli (gas exchange site). Alveoli features: thin walls (one cell), large surface area, rich capillary network — maximise diffusion of O2 into blood and CO2 out.", example: "During exercise, breathing rate increases from ~15 to up to 60 breaths/min to meet oxygen demand" },
    { term: "Flexibility Training Methods", definition: "Static stretching: holding a stretch at end of range (20–30 seconds). PNF (Proprioceptive Neuromuscular Facilitation): contract-relax technique achieving greater range than static alone. Dynamic stretching: controlled movement through range (used in warm-up). Ballistic: bouncing (high injury risk, not recommended).", example: "PNF hamstring stretch: push against resistance, then relax — achieves significantly greater range of motion" },
    { term: "Cardiovascular Drift", definition: "During prolonged exercise in heat, stroke volume gradually falls as blood is diverted to skin for cooling. Heart rate must increase to maintain cardiac output — this progressive rise in HR over time is called cardiovascular drift.", example: "Marathon runner maintains pace but HR rises over the final miles as body prioritises cooling" },
    { term: "Altitude Training", definition: "Training at high altitude (1800m+) where reduced partial pressure of O2 stimulates increased EPO production → more red blood cells → higher haemoglobin and O2-carrying capacity. Benefits persist 2–4 weeks on return to sea level.", example: "Kenyan distance runners live and train at altitude in the Rift Valley (~2400m), contributing to endurance dominance" },
  ],
};
